#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[4][5];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 5; j++)
            plik >> m[i][j];
    cout << "Suma wierszy:" << endl;
    int maxS = 0, maxR = 0, minS = 1000000, minR = 0;
    for (int i = 0; i < 4; i++) {
        int s = 0;
        for (int j = 0; j < 5; j++) s += m[i][j];
        cout << "   Wiersz " << i + 1 << ": " << s << endl;
        if (s > maxS) { maxS = s; maxR = i + 1; }
        if (s < minS) { minS = s; minR = i + 1; }
    }
    cout << "Wiersz z max suma: " << maxR << " (" << maxS << ")" << endl;
    cout << "Wiersz z min suma: " << minR << " (" << minS << ")" << endl;
    return 0;
}
```

Weryfikacja:
- Wiersz 1: 3+7+1+4+5 = 20
- Wiersz 2: 2+8+6+3+1 = 20
- Wiersz 3: 9+4+2+7+8 = 30
- Wiersz 4: 5+1+3+6+4 = 19
- Max: wiersz 3 (30), Min: wiersz 4 (19)
